import {bootstrap as annualBootstrap,uid,hash} from './annual-position-budget-synthetic.js';
import {annualBudgetFingerprint} from '../../lib/internal-annual-position-budget.js';
export {uid,hash};
export const subject=()=>({contractId:uid(1),legajo:'7',employeeName:'Persona exclusivamente sintética QA',identityToken:hash('c'),sourceCutoff:null,origin:'MUNICONTROL',registrationId:uid(2),registeredAt:'2026-01-01T12:00:00Z'});
export const source=()=>({instrument:'Acto exclusivamente sintético QA',documentSha256:hash('e'),reference:'Documento inventado para pruebas'});
export function reference(patch={}){const annual=annualBootstrap({approved:true});return {id:uid(20),budgetRevision:1,definitionSha256:annual.catalog.definitionSha256,rowCode:'QA0001',validFrom:'2026-01-01',validTo:'2026-12-31',quantity:'18.000000000000000001',source:source(),...patch};}
export function resolved(patch={}){const ref=reference(patch),annual=annualBootstrap({approved:true});return {...ref,normative:{approvalId:annual.catalog.approvalId,proposalId:annual.catalog.proposalId,row:annual.catalog.definition.rows.find(r=>r.code===ref.rowCode),source:annual.catalog.definition.source}};}
export function command(patch={}){return {command:'propose',contractId:uid(1),year:2026,scopeVersion:hash('a'),baseVersion:hash('b'),annualVersion:hash('b'),reason:'Asignación exclusivamente sintética QA',reviewConfirmed:false,allocations:[reference()],...patch};}
export function bootstrap({approved=false}={}){const body=command(),a=resolved(),id=uid(30);return {version:'position-assignment.v1',contractId:uid(1),year:2026,subject:subject(),scopeVersion:hash('a'),state:{version:hash('b'),revision:approved?1:0,proposalId:approved?id:null,approvalId:approved?uid(31):null,allocations:approved?[a]:[]},annual:annualBootstrap({approved:true}),proposals:[{id,body,requestSha256:annualBudgetFingerprint(body),allocations:[a],createdAt:'2026-10-01T12:00:00Z',authorLabel:'Preparador sintético QA',canReview:!approved,status:approved?'approved':'pending',decision:approved?{id:uid(31),command:'approve',reason:'Decisión exclusivamente sintética QA',actorLabel:'Revisor sintético QA',recordedAt:'2026-10-01T13:00:00Z',revision:1}:null}],proposalCount:1,complete:true,permissions:{canPropose:true,canReview:true}};}
export function runCapture(count=1){const payload={version:'own-position-population.v1',populationVersion:hash('f'),complete:true,employeeCount:count,employees:Array.from({length:count},(_,i)=>({contractId:uid(100+i),employeeNumber:String(7+i).padStart(3,'0'),identityToken:hash('c'),status:'assigned',assignmentRevision:1,assignmentVersion:hash('b'),allocations:[{...resolved({id:uid(1000+i)}),coverage:'full'}]}))};return {version:'own-run-position-capture.v1',captureId:uid(80),status:'captured',capturePayloadSha256:hash('a'),period:'2026-10',liquidationType:'monthly',payload,payloadSha256:annualBudgetFingerprint(payload)};}
